(6292934, 931530, 126722, '<td valign="top">i like the shot, but i''m not sure about the square crop.  I would have given the front wheel a bit more space on the left.  nice exposure and nice crisp editing.</td>', 'i like the shot, but i''m not sure about the square crop.  I would have given the front wheel a bit more space on the left.  nice exposure and nice crisp editing.', '2011-01-24 17:01:29.000000', NULL, 1),
(6292938, 931507, 126722, '<td valign="top">I love the repetition and the composition.  I would have liked something to stop me on one of the wheels though, something to keep me interested on one in particular..... like a solider in line but making a silly face..... something to set one wheel out from the rest.</td>', 'I love the repetition and the composition.  I would have liked something to stop me on one of the wheels though, something to keep me interested on one in particular..... like a solider in line but making a silly face..... something to set one wheel out from the rest.', '2011-01-24 17:05:24.000000', NULL, 1),
(6292939, 930746, 126722, '<td valign="top">i didn''t like it at first, composition didn''t work for me or the motion blur, but the hidden meaning inside the shot made me feel sympathy for the handicapped person.</td>', 'i didn''t like it at first, composition didn''t work for me or the motion blur, but the hidden meaning inside the shot made me feel sympathy for the handicapped person.', '2011-01-24 17:06:51.000000', NULL, 1),
(6292949, 931474, 126722, '<td valign="top">you did a great job with the mono tone of the image.  nice motion of the water as well.</td>', 'you did a great job with the mono tone of the image.  nice motion of the water as well.', '2011-01-24 17:15:27.000000', NULL, 1),
(6292962, 931581, 126722, '<td valign="top">nice lighting</td>', 'nice lighting', '2011-01-24 17:26:40.000000', NULL, 1);
