(6292980, 931409, 126722, '<td valign="top">nice shot, love the motion blur</td>', 'nice shot, love the motion blur', '2011-01-24 17:39:16.000000', NULL, 1),
(6292981, 931267, 108069, '<td valign="top">Quite the perspective. The exposure range is unbelievable and the tone mapping is really, really well done. Nice colors and very interesting.</td>', 'Quite the perspective. The exposure range is unbelievable and the tone mapping is really, really well done. Nice colors and very interesting.', '2011-01-24 17:39:43.000000', NULL, 1),
