(6292997, 931386, 108069, '<td valign="top">Cool shot. Great motion and beautiful rims to have as a subject with great composition. Looking forward to checking out the set up. Great job.</td>', 'Cool shot. Great motion and beautiful rims to have as a subject with great composition. Looking forward to checking out the set up. Great job.', '2011-01-24 17:48:35.000000', NULL, 1),
(6293000, 931530, 113419, '<td valign="top">EXCELLENT</td>', 'EXCELLENT', '2011-01-24 17:49:27.000000', NULL, 1),
(6293003, 931473, 108069, '<td valign="top">Great contrast and lighting. Truly a professional shot with compelling composition. A pleasure to view this.</td>', 'Great contrast and lighting. Truly a professional shot with compelling composition. A pleasure to view this.', '2011-01-24 17:51:13.000000', NULL, 1),
(6293005, 931606, 113419, '<td valign="top">Is this the 4th buggy wheels I''ve seen!  I can''t believe it!  :-)  Yours is the first one with snow.  I''m loving these!</td>', 'Is this the 4th buggy wheels I''ve seen!  I can''t believe it!  :-)  Yours is the first one with snow.  I''m loving these!', '2011-01-24 17:51:43.000000', NULL, 1),
