(6293010, 931502, 113419, '<td valign="top">My first thought was to rate this a 5 or lower....but the more I looked at it the more I liked it....I''m giving you a 7.</td>', 'My first thought was to rate this a 5 or lower....but the more I looked at it the more I liked it....I''m giving you a 7.', '2011-01-24 17:54:56.000000', NULL, 1),
(6293011, 931241, 108069, '<td valign="top">Beautiful scene. Not a fan of the red in the border, but I do similar at times so I get it. Nicely composed and very pleasing image. Nice work.</td>', 'Beautiful scene. Not a fan of the red in the border, but I do similar at times so I get it. Nicely composed and very pleasing image. Nice work.', '2011-01-24 17:56:02.000000', NULL, 1),
(6293020, 931544, 108069, '<td valign="top">Cool shot. Pun partly intended. Nice perspective and great feel. Nicely done.</td>', 'Cool shot. Pun partly intended. Nice perspective and great feel. Nicely done.', '2011-01-24 18:05:40.000000', NULL, 1),
(6293021, 931222, 126722, '<td valign="top">has a nice country western film feel. not sure about the crop on it</td>', 'has a nice country western film feel. not sure about the crop on it', '2011-01-24 18:06:48.000000', NULL, 1),
