(6293699, 931446, 108069, '<td valign="top">Cool idea and nice image. I think it may be suffering from a bit of oversharpening, but the shallow DoF is nice to bring the focus to the wheel.</td>', 'Cool idea and nice image. I think it may be suffering from a bit of oversharpening, but the shallow DoF is nice to bring the focus to the wheel.', '2011-01-25 13:21:10.000000', NULL, 1),
(6293712, 931541, 108069, '<td valign="top">Precision photo. Nice detail and use of light to capture all the interesting layers. Very well done.</td>', 'Precision photo. Nice detail and use of light to capture all the interesting layers. Very well done.', '2011-01-25 13:36:48.000000', NULL, 1),
