(6294610, 931266, 126694, '<td valign="top">Huston... we have a problem!!!</td>', 'Huston... we have a problem!!!', '2011-01-26 06:39:58.000000', NULL, 1),
(6294662, 931215, 63616, '<td valign="top">Wonderful visualization. Excellent contrast</td>', 'Wonderful visualization. Excellent contrast', '2011-01-26 08:11:10.000000', NULL, 1),
(6294795, 931201, 124982, '<td valign="top">For some reason, this bent and buckled wheel really appeals to me. Wish the background was out of focus though, since it pulls your attention away from the wheel.</td>', 'For some reason, this bent and buckled wheel really appeals to me. Wish the background was out of focus though, since it pulls your attention away from the wheel.', '2011-01-26 10:44:39.000000', NULL, 1),
(6294866, 931535, 124982, '<td valign="top">Originally I felt this picture was too busy for my liking. But I''ve come back to it time and time again and it''s grown on me. It''s a very "geometric" picture, with lots of lines and shapes, and while it looks busy, it''s actually starting to appeal to me. If the wheel was any smaller, it would get way too lost in all this, but with such a prominent wheel, it manages to hold its own quite well! Just love the texture of the wood in the wheel and the rivets give it some added dimension of complexity to let the eye look at.<br/> <br/>Overall, a really nice photo - top 10 for me!</td>', 'Originally I felt this picture was too busy for my liking. But I''ve come back to it time and time again and it''s grown on me. It''s a very "geometric" picture, with lots of lines and shapes, and while it looks busy, it''s actually starting to appeal to me. If the wheel was any smaller, it would get way too lost in all this, but with such a prominent wheel, it manages to hold its own quite well! Just love the texture of the wood in the wheel and the rivets give it some added dimension of complexity to let the eye look at. Overall, a really nice photo - top 10 for me!', '2011-01-26 12:16:12.000000', NULL, 1),
(6294867, 931516, 124982, '<td valign="top">Slightly flat for my liking, some more highlights and shadows would do wonders for adding depth and character to this photo.</td>', 'Slightly flat for my liking, some more highlights and shadows would do wonders for adding depth and character to this photo.', '2011-01-26 12:17:38.000000', NULL, 1),
(6294870, 930946, 124982, '<td valign="top">Originally gave this a 5 because I felt the cogs were a little out of focus, but seems to be better on my work monitor. Really like the minimalist approach and use of B&amp;W.</td>', 'Originally gave this a 5 because I felt the cogs were a little out of focus, but seems to be better on my work monitor. Really like the minimalist approach and use of B&W.', '2011-01-26 12:20:08.000000', NULL, 1),
(6295219, 931520, 41864, '<td valign="top">Gorgeous tones - love the blues and browns.</td>', 'Gorgeous tones - love the blues and browns.', '2011-01-26 17:51:21.000000', NULL, 1),
(6295220, 931204, 41864, '<td valign="top">Great motion shot, love the expression. Not voting.</td>', 'Great motion shot, love the expression. Not voting.', '2011-01-26 17:52:33.000000', NULL, 1),
