(6297134, 931121, 76335, '<td valign="top">I have a sizable CD collection, but this image reminds me that nothing was more warm and satisfying than analog audio.</td>', 'I have a sizable CD collection, but this image reminds me that nothing was more warm and satisfying than analog audio.', '2011-01-29 13:39:01.000000', NULL, 1),
(6297135, 931199, 76335, '<td valign="top">Black and white was a very inspired (if not ingenious) choice for this. The way the metal of the gears blends in with the background, and the dramatic lighting -- makes those cogs really cut like teeth.</td>', 'Black and white was a very inspired (if not ingenious) choice for this. The way the metal of the gears blends in with the background, and the dramatic lighting -- makes those cogs really cut like teeth.', '2011-01-29 13:41:50.000000', NULL, 1),
(6297136, 931714, 76335, '<td valign="top">Nice. Looks like something I''d see on a motorcycle calendar.</td>', 'Nice. Looks like something I''d see on a motorcycle calendar.', '2011-01-29 13:42:47.000000', NULL, 1),
(6297137, 931453, 76335, '<td valign="top">I wasn''t sure about the framing -- the bar at the bottom -- but I think it works just fine. Nice tones.</td>', 'I wasn''t sure about the framing -- the bar at the bottom -- but I think it works just fine. Nice tones.', '2011-01-29 13:43:28.000000', NULL, 1),
(6297139, 931724, 76335, '<td valign="top">Great subject, but I''m not sure such a tight crop was necessary. It''s an imposing enough subject, and some context would be welcome. Also, the lighting''s a bit challenging.</td>', 'Great subject, but I''m not sure such a tight crop was necessary. It''s an imposing enough subject, and some context would be welcome. Also, the lighting''s a bit challenging.', '2011-01-29 13:45:56.000000', NULL, 1),
(6297140, 930900, 76335, '<td valign="top">For such a birght scene, the processing makes it feel dull. Also, I think a white balance adjustment is in order here.</td>', 'For such a birght scene, the processing makes it feel dull. Also, I think a white balance adjustment is in order here.', '2011-01-29 13:47:30.000000', NULL, 1),
(6297141, 931278, 76335, '<td valign="top">Indeed! And those are some wheels. The focus feels a bit soft (that or it''s motion blur).</td>', 'Indeed! And those are some wheels. The focus feels a bit soft (that or it''s motion blur).', '2011-01-29 13:48:36.000000', NULL, 1),
(6297142, 931715, 76335, '<td valign="top">The ice demands attention, but unfortunately the highlights are blown. Good subject matter though.</td>', 'The ice demands attention, but unfortunately the highlights are blown. Good subject matter though.', '2011-01-29 13:49:24.000000', NULL, 1),
